{"title": "PTV adoption per month by municipality", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "PTV adoption per month by municipality",
  "data": {
    "url": {
      "index": "analytics",
      "body": {
        "size": 0,
        "query": {
          "exists": {
            "field": "ptv.org-id"
          }
        },
        "aggs": {
          "sites": {
            "terms": {
              "field": "lipas-id",
              "size": 20000
            },
            "aggs": {
              "first": {
                "min": {
                  "field": "event-date"
                }
              },
              "city": {
                "terms": {
                  "field": "search-meta.location.city.name.fi.keyword",
                  "size": 1
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.sites.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.first.value",
      "as": "first"
    },
    {
      "calculate": "length(datum.city.buckets) ? datum.city.buckets[0].key : '(tuntematon)'",
      "as": "municipality"
    },
    {
      "timeUnit": "utcyearmonth",
      "field": "first",
      "as": "month"
    },
    {
      "aggregate": [
        {
          "op": "count",
          "as": "new"
        }
      ],
      "groupby": [
        "month",
        "municipality"
      ]
    }
  ],
  "mark": {
    "type": "bar",
    "tooltip": true
  },
  "encoding": {
    "x": {
      "field": "month",
      "type": "temporal",
      "timeUnit": "utcyearmonth",
      "title": "Month",
      "axis": {
        "format": "%Y-%m",
        "labelAngle": -45
      }
    },
    "y": {
      "field": "new",
      "type": "quantitative",
      "title": "New integrations",
      "stack": "zero"
    },
    "color": {
      "field": "municipality",
      "type": "nominal",
      "title": "Municipality",
      "scale": {
        "scheme": "tableau20"
      }
    },
    "tooltip": [
      {
        "field": "month",
        "type": "temporal",
        "timeUnit": "utcyearmonth",
        "title": "Month",
        "format": "%Y-%m"
      },
      {
        "field": "municipality",
        "type": "nominal",
        "title": "Municipality"
      },
      {
        "field": "new",
        "type": "quantitative",
        "title": "New"
      }
    ]
  }
}"}}

